import { createApp } from '../src/app.js'
import { headers } from './helpers.js'

describe('items', () => {
  let app: Express

  // A new application per test: every test starts with empty storage
  beforeEach(() => {
    app = createApp()
  })

  it('list items answers 501 until the storage is written', async () => {
    const response = await request(app).get('/items').set(headers)
    expect(response.status).toBe(501)
    expect(response.body.error.code).toBe('not_implemented')
  })

  it('get item answers 501 until the storage is written', async () => {
    const response = await request(app).get('/items/999999').set(headers)
    expect(response.status).toBe(501)
    expect(response.body.error.code).toBe('not_implemented')
  })

  it('list items needs credentials', async () => {
    const response = await request(app).get('/items')
    expect(response.status).toBe(401)
    expect(response.body.error.code).toBe('unauthorized')
  })
})

